// Prompt/version lock (T3.12). The layer-2 cache is keyed by PROMPT_VERSION
// (CONTRATO §5–6), so a prompt edit that ships without a version bump would keep
// serving explanations generated by the *old* prompt — and the eval report for
// "v2" would no longer describe what v2 produces. The lock pins the sha256 of
// prompts.ts to the version it was written for; a test fails when they drift.
//
// Update with `pnpm --filter @fuchine/llm prompt:lock` (refuses unless
// PROMPT_VERSION was bumped). Not exported from the package index: node-only.

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export type PromptLock = {
  promptVersion: number;
  promptsSha256: string;
};

export const PROMPTS_FILE = fileURLToPath(new URL("./prompts.ts", import.meta.url));
export const CONTRACT_FILE = fileURLToPath(new URL("./contract.ts", import.meta.url));
export const LOCK_FILE = fileURLToPath(new URL("./prompt-version.lock.json", import.meta.url));

/** sha256 of the prompts source, line endings normalized (CRLF checkouts hash the same). */
export function hashPrompts(source: string): string {
  return createHash("sha256").update(source.replace(/\r\n/g, "\n")).digest("hex");
}

/** PROMPT_VERSION read from contract.ts source (the lock script runs without importing it). */
export function readPromptVersion(contractSource: string): number {
  const m = /export const PROMPT_VERSION\s*=\s*(\d+)\s*;/.exec(contractSource);
  if (!m) throw new Error("PROMPT_VERSION not found in contract.ts");
  return Number(m[1]);
}

export type LockVerdict =
  | { ok: true }
  | { ok: false; reason: "prompt_changed_without_bump" | "version_downgrade" | "stale_lock"; message: string };

const UPDATE_HINT = "run `pnpm --filter @fuchine/llm prompt:lock`";

/** Compare the current (version, hash) against the lock. Pure — unit-tested. */
export function checkPromptLock(current: PromptLock, lock: PromptLock): LockVerdict {
  const sameHash = current.promptsSha256 === lock.promptsSha256;
  if (current.promptVersion < lock.promptVersion) {
    return {
      ok: false,
      reason: "version_downgrade",
      message:
        `PROMPT_VERSION went down (${lock.promptVersion} -> ${current.promptVersion}). ` +
        `Versions only move forward: old cache rows would be served for the new prompt.`,
    };
  }
  if (current.promptVersion === lock.promptVersion) {
    if (sameHash) return { ok: true };
    return {
      ok: false,
      reason: "prompt_changed_without_bump",
      message:
        `packages/llm/src/prompts.ts changed but PROMPT_VERSION is still ${lock.promptVersion}. ` +
        `A prompt edit must bump PROMPT_VERSION (contract.ts) — the shared explanation cache ` +
        `is keyed by it — then ${UPDATE_HINT}. Run the eval (eval:explain) before deciding.`,
    };
  }
  return {
    ok: false,
    reason: "stale_lock",
    message:
      `PROMPT_VERSION is ${current.promptVersion} but the lock still pins v${lock.promptVersion}: ${UPDATE_HINT}.`,
  };
}

export function readCurrentLockState(): PromptLock {
  return {
    promptVersion: readPromptVersion(readFileSync(CONTRACT_FILE, "utf8")),
    promptsSha256: hashPrompts(readFileSync(PROMPTS_FILE, "utf8")),
  };
}

export function readLockFile(): PromptLock {
  return JSON.parse(readFileSync(LOCK_FILE, "utf8")) as PromptLock;
}
